// bd codegen — validate block manifests and generate engine (C++) + web (TS) code from them (DATA-0002).
//   pnpm bd codegen           validate + write generated files
//   pnpm bd codegen --check   validate + fail if generated files are stale (CI)
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, relative } from 'node:path';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const Ajv2020 = require('ajv/dist/2020').default;

const BLOCKS_DIR = 'blocks';
const OUT_CPP = 'engine/include/blokdust/generated/blocks.gen.hpp';
const OUT_TS = 'web/src/generated/blocks.gen.ts';
const OUT_PALETTES_TS = 'web/src/generated/palettes.gen.ts';
const HEADER = 'GENERATED by `pnpm bd codegen` from blocks/**/*.block.json. Do not edit by hand.';

// Category folder must match the manifest category (schema enum).
const KIND_CPP: Record<string, string> = {
  'audio-source': 'AudioSource',
  'pre-effect': 'PreEffect',
  'post-effect': 'PostEffect',
  'power-source': 'PowerSource',
  'power-effect': 'PowerEffect',
  logic: 'Logic',
  void: 'Void',
  controller: 'Controller',
  // v2-only kinds (SCOPE-0005): gate = a Void that power opens (Gate); path = acts on a particle or beam in its path
  // (Prism); listener = hears the sources connected to it (Sound Laser); modulator = connects to any block and moves a
  // param (LFO).
  gate: 'Gate',
  path: 'Path',
  listener: 'Listener',
  modulator: 'Modulator',
};

const walk = (d: string): string[] =>
  readdirSync(d).flatMap((f) =>
    statSync(join(d, f)).isDirectory() ? walk(join(d, f)) : [join(d, f)],
  );
const pascal = (id: string) =>
  id
    .split(/[.-]/)
    .map((s) => s[0].toUpperCase() + s.slice(1))
    .join('');
const cppIdent = (s: string) => (/^[A-Za-z_]\w*$/.test(s) ? s : s.replace(/\W/g, '_'));
const num = (n: number) => {
  if (!Number.isFinite(n)) throw new Error(`non-finite number ${n}`);
  const s = String(n);
  return /[.e]/.test(s) ? s : `${s}.0`;
};
const fnum = (n: number) => `${num(n)}f`;

function loadAndValidate() {
  const schema = JSON.parse(readFileSync(join(BLOCKS_DIR, 'schema/block.schema.json'), 'utf8'));
  const ajv = new Ajv2020({ allErrors: true, strict: false });
  const validate = ajv.compile(schema);
  const errors: string[] = [];
  const manifests: any[] = [];
  for (const f of walk(BLOCKS_DIR)
    .filter((f) => f.endsWith('.block.json'))
    .sort()) {
    const m = JSON.parse(readFileSync(f, 'utf8'));
    if (!validate(m))
      for (const e of validate.errors ?? [])
        errors.push(`${f}: ${e.instancePath || '/'} ${e.message}`);
    if (basename(f) !== `${m.id}.block.json`)
      errors.push(`${f}: filename must be ${m.id}.block.json`);
    if (basename(dirname(f)) !== m.category) errors.push(`${f}: folder must be ${m.category}/`);
    const keys = new Set<string>();
    for (const p of m.params ?? []) {
      if (keys.has(p.key)) errors.push(`${f}: duplicate param ${p.key}`);
      keys.add(p.key);
    }
    manifests.push({ ...m, _file: f });
  }
  const ids = new Set<string>();
  for (const m of manifests) {
    if (ids.has(m.id)) errors.push(`${m._file}: duplicate id ${m.id}`);
    ids.add(m.id);
  }
  // Stable order: category order as in v1 menus, then id.
  const catOrder = ['source', 'effect', 'power', 'interaction'];
  manifests.sort(
    (a, b) =>
      catOrder.indexOf(a.category) - catOrder.indexOf(b.category) || a.id.localeCompare(b.id),
  );
  return { manifests, errors };
}

/** Automation mapping for a param: explicit `range` (real units) wins; otherwise invert v1's slider expression. */
export function automation(p: any): { transform: string; min: number; max: number; k: number } {
  const none = { transform: 'None', min: 0, max: 0, k: 0 };
  if (Array.isArray(p.range))
    return { transform: 'Identity', min: p.range[0], max: p.range[1], k: 0 };
  const props = p.v1?.ui?.props;
  if (
    p.v1?.ui?.type !== 'slider' ||
    typeof props?.min !== 'number' ||
    typeof props?.max !== 'number'
  )
    return none;
  const e = (p.v1.uiValueExpr ?? '').replace(/\s+/g, '');
  const key = p.key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const n = '(-?\\d+(?:\\.\\d+)?)';
  let m: RegExpExecArray | null;
  const base = { min: props.min, max: props.max };
  if (e === `this.Params.${p.key}`) return { transform: 'Identity', ...base, k: 0 };
  if (
    (m = new RegExp(`^${n}-this\\.Params\\.${key}$`).exec(e)) ||
    (m = new RegExp(`^Math\\.round\\(${n}-this\\.Params\\.${key}\\)$`).exec(e))
  )
    return { transform: 'SubtractFrom', ...base, k: Number(m[1]) }; // ui = k − param  ⇒ param = k − ui
  if ((m = new RegExp(`^this\\.Params\\.${key}\\+${n}$`).exec(e)))
    return { transform: 'Minus', ...base, k: Number(m[1]) }; // ui = param + k
  if ((m = new RegExp(`^this\\.Params\\.${key}\\*${n}$`).exec(e)))
    return { transform: 'Divide', ...base, k: Number(m[1]) }; // ui = param · k
  return none;
}

function genCpp(manifests: any[]): string {
  const maxParams = Math.max(...manifests.map((m) => m.params.length));
  const L: string[] = [];
  L.push(
    `// ${HEADER}`,
    '#pragma once',
    '',
    '#include <array>',
    '#include <cstddef>',
    '#include <cstdint>',
    '#include <string_view>',
    '',
    'namespace blokdust::gen {',
    '',
    `inline constexpr std::size_t kBlockTypeCount = ${manifests.length};`,
    `inline constexpr std::size_t kMaxParams = ${maxParams};`,
    '',
    'enum class BlockType : std::uint16_t {',
  );
  for (const m of manifests) L.push(`  ${pascal(m.id)},  // ${m.id}`);
  L.push('};', '', 'enum class BlockKind : std::uint8_t {');
  for (const k of Object.values(KIND_CPP)) L.push(`  ${k},`);
  L.push(
    '};',
    '',
    'struct GridPoint { float x; float y; };',
    '',
    '/// How a normalised host value (0..1, Dust 1–8 automation, PLUGIN-0003) maps onto this param:',
    '/// ui = uiMin + v·(uiMax − uiMin) on the v1 slider, then param = transform(ui). None = not automatable.',
    'enum class UiTransform : std::uint8_t { None, Identity, SubtractFrom /* k − ui */, Minus /* ui − k */, Divide /* ui ÷ k */ };',
    '',
    '/// Param default. numeric=false marks v1 params with non-numeric defaults (strings/objects), stored as 0.',
    '/// log: the slider is logarithmic (an LFO moves the param in octaves, AUDIO-0003).',
    'struct ParamInfo { std::string_view key; double defaultValue; bool numeric; UiTransform transform; double uiMin; double uiMax; double k; bool log = false; };',
    '',
    'struct BlockInfo {',
    '  BlockType type;',
    '  std::string_view id;',
    '  std::string_view v1Type;',
    '  BlockKind kind;',
    '  float catchment;            // grid units; 0 = never the effect side of a connection',
    '  const GridPoint* outline;   // hit-test polygon (grid units, relative to block position)',
    '  std::uint8_t outlineCount;',
    '  const ParamInfo* params;',
    '  std::uint8_t paramCount;',
    '  bool draft;',
    '};',
    '',
  );
  for (const m of manifests) {
    const P = pascal(m.id);
    L.push(`// ---- ${m.id} (${m.name})`);
    L.push(
      `inline constexpr GridPoint kOutline${P}[] = {${m.geometry.outline.map(([x, y]: number[]) => `{${fnum(x)}, ${fnum(y)}}`).join(', ')}};`,
    );
    if (m.params.length) {
      L.push(`inline constexpr ParamInfo kParams${P}[] = {`);
      for (const p of m.params) {
        const d = p.default;
        const numeric = typeof d === 'number' || typeof d === 'boolean';
        const v = typeof d === 'number' ? d : typeof d === 'boolean' ? (d ? 1 : 0) : 0;
        const a = automation(p);
        L.push(
          `  {"${p.key}", ${num(v)}, ${numeric}, UiTransform::${a.transform}, ${num(a.min)}, ${num(a.max)}, ${num(a.k)}${p.curve === 'log' ? ', true' : ''}},`,
        );
      }
      L.push('};');
    }
    L.push(
      `namespace param::${P} { enum : std::uint8_t { ${[...m.params.map((p: any) => cppIdent(p.key)), 'Count'].join(', ')} }; }`,
      '',
    );
  }
  L.push('inline constexpr std::array<BlockInfo, kBlockTypeCount> kBlocks{{');
  for (const m of manifests) {
    const P = pascal(m.id);
    L.push(
      `  {BlockType::${P}, "${m.id}", "${m.v1?.type ?? ''}", BlockKind::${KIND_CPP[m.kind]}, ${fnum(m.connection?.catchment ?? 0)}, ` +
        `kOutline${P}, ${m.geometry.outline.length}, ${m.params.length ? `kParams${P}` : 'nullptr'}, ${m.params.length}, ${m.draft}},`,
    );
  }
  L.push(
    '}};',
    '',
    'constexpr const BlockInfo& info(BlockType t) { return kBlocks[static_cast<std::size_t>(t)]; }',
    '',
    'constexpr bool findBlockType(std::string_view id, BlockType& out) {',
    '  for (const auto& b : kBlocks) if (b.id == id) { out = b.type; return true; }',
    '  return false;',
    '}',
    '',
    '}  // namespace blokdust::gen',
    '',
  );
  return L.join('\n');
}

function genTs(manifests: any[]): string {
  const data = manifests.map((m) => ({
    id: m.id,
    category: m.category,
    kind: m.kind,
    name: m.name,
    description: m.description,
    draft: m.draft,
    v1Type: m.v1?.type ?? null,
    menuId: m.v1?.type ?? m.name.replace(/[^A-Za-z0-9]/g, ''),
    catchment: m.connection?.catchment ?? 0,
    geometry: m.geometry,
    params: m.params.map((p: any) => ({
      key: p.key,
      default: p.default,
      unit: p.unit ?? null,
      ui: automation(p),
    })),
  }));
  return (
    `// ${HEADER}\n` +
    `/* eslint-disable */\n\n` +
    `export type BlockKind = ${[...new Set(Object.keys(KIND_CPP))].map((k) => `'${k}'`).join(' | ')};\n` +
    `export interface GeometryLayer { palette: number; points: [number, number][]; kind?: 'pixel'; units?: 'unit'; anchor?: 'randomStar'; alpha?: number }\n` +
    `export interface Overlay { name: string; scale: 'screen' | 'world'; states: Record<string, GeometryLayer[]> }\n` +
    `export interface BlockGeometry { units: 'grid'; unitsPerGrid?: number; layers: GeometryLayer[]; /** Drawn instead of layers while a Gate is open (SIMULATION-0011). */ openLayers?: GeometryLayer[]; outline: [number, number][]; menuOffset?: [number, number]; overlays?: Overlay[] }\n` +
    `export interface BlockDef { id: string; category: string; kind: BlockKind; name: string; description: string; draft: boolean; v1Type: string | null; /** The block's id in the menus: v1's type name, or the name without spaces for v2-only blocks. */ menuId: string; catchment: number; geometry: BlockGeometry; params: { key: string; default: unknown; unit: string | null; ui: { transform: 'None' | 'Identity' | 'SubtractFrom' | 'Minus' | 'Divide'; min: number; max: number; k: number } }[] }\n\n` +
    `export const BLOCKS: readonly BlockDef[] = ${JSON.stringify(data, null, 2)} as const as unknown as readonly BlockDef[];\n\n` +
    `export type BlockId = ${manifests.map((m) => `'${m.id}'`).join(' | ')};\n\n` +
    `export const BLOCKS_BY_ID: ReadonlyMap<string, BlockDef> = new Map(BLOCKS.map(b => [b.id, b]));\n`
  );
}

function genPalettesTs(): string {
  const p = JSON.parse(readFileSync(join(BLOCKS_DIR, 'v1-palettes.json'), 'utf8'));
  const themes = p.themes.map((t: any) => ({
    index: t.index,
    name: t.name,
    colors: t.colors,
    roles: t.roles,
  }));
  return (
    `// GENERATED by \`pnpm bd codegen\` from blocks/v1-palettes.json. Do not edit by hand.\n\n` +
    `export interface Theme { index: number; name: string; colors: string[]; roles: { txt: number; menu: number[]; options: number[]; power: number } }\n\n` +
    `export const THEMES: readonly Theme[] = ${JSON.stringify(themes, null, 2)};\n`
  );
}

const check = process.argv.includes('--check');
const { manifests, errors } = loadAndValidate();
for (const e of errors) console.error(`error: ${e}`);
if (errors.length) {
  console.log(JSON.stringify({ manifests: manifests.length, errors: errors.length }));
  process.exit(1);
}

const outputs: [string, string][] = [
  [OUT_CPP, genCpp(manifests)],
  [OUT_TS, genTs(manifests)],
  [OUT_PALETTES_TS, genPalettesTs()],
];
let stale = 0;
for (const [path, content] of outputs) {
  const cur = existsSync(path) ? readFileSync(path, 'utf8') : null;
  if (cur === content) continue;
  if (check) {
    stale++;
    console.error(`stale: ${path}`);
    continue;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.error(`wrote ${relative('.', path)}`);
}
console.log(
  JSON.stringify({
    manifests: manifests.length,
    drafts: manifests.filter((m) => m.draft).length,
    errors: 0,
    stale,
  }),
);
if (stale) process.exit(1);
